"""Destination `sas_restructured`: generated by package-factory from approved specs. Do not edit here.

Requirement (approved):
  Deliver into the same S3 bucket as the source (region eu-north-1). Each package is one file whose package path is the path relative to incoming/ (first folder = study ID, used exactly as written). The target is decided from the folder path only (path without the file name); the file name is always kept. Data format from the folder path: adam if it contains /adam/, otherwise sdtm if it contains /sdtm/, otherwise raw if it contains raw/ (so restricted_raw/ also counts as raw). For anonymised folders the data format comes from _adam_, _sdtm_, _raw_ or _restricted_raw_ (= raw). 'Last folder' = the folder that directly contains the file. Every rule is checked; exactly one rule must match. 1. CDAP: path contains /data_reuse/ and /cdap_ and a data format. If it contains /cdap_csr -> {study}/extended_primary_use/primary/{format}/{file}. Else if the last folder contains _ia -> take the third '_' part of the last folder (cdap_20210617_ia300 -> ia300) and write it as ia_ + the rest (ia_300) -> {study}/extended_primary_use/interim/{format}/ia_300/{file}; fewer than 3 parts -> error. Else -> second '_' part of the last folder (cdap_20210617 -> 20210617) -> {study}/extended_primary_use/other/{format}/20210617/{file}; fewer than 2 parts -> error. 2. IDAP: path contains /data_reuse/ and /idap and a data format -> {study}/internal_reuse/{format}/{last folder}/{file}. 3. MED: path contains /data_reuse/ and /med and a data format -> {study}/external_reuse/{format}/{last folder}/{file}. 4. ANON: path contains _anon_ and an underscore data format (_adam_, _sdtm_, _raw_, _restricted_raw_). If it contains _anon_csr -> {study}/anonymised/primary/{format}/{file}. Else take the last '_' part of the last folder: starts with lowercase ia (case-sensitive, e.g. ia500) -> {study}/anonymised/interim/{format}/ia_500/{file}; otherwise (e.g. 20220120) -> {study}/anonymised/other/{format}/20220120/{file}. 5. CDAR: path contains /cdar/ and a data format. Reporting level = the folder right after the folder named 'ar' (case-insensitive, compared in lowercase). No 'ar' folder, or reporting level is adam, sdtm or raw -> error. csr -> {study}/primary/complete/{format}/{file}. Starts with ia -> remove 'ia' and any leading '_', then add 'ia_' (ia1 -> ia_1, ia_psc -> ia_psc) -> {study}/primary/interim/{format}/{ia_x}/{file}. Anything else (bdr200) -> {study}/primary/other/{format}/bdr200/{file}. 6. OTHERS: path contains /data_reuse/ and a data format, and none of /med, /cdap, /idap, /anon, _anon_ -> {study}/other/{format}/{last folder}/{file}. 7. DEFAULT (pass-through): path has none of /data_reuse/, _anon_, /cdar/ -> the same path (incoming/ removed). If no rule matches, more than one rule matches, or the target cannot be worked out -> move the file to error/{path without incoming/}. Never drop a file. Examples: incoming/d0000c00004/root/cdar/d000/d0000c00004/ar/ia100/sdtm/dev/data/data_area/b.sas7bdat -> d0000c00004/primary/interim/sdtm/ia_100/b.sas7bdat; incoming/ABCD-0000-0000/x.pdf -> ABCD-0000-0000/x.pdf. DELIVERY BEHAVIOUR: Move, not copy: copy server-side (files can be larger than 5 GiB), confirm the target exists, then delete the source from incoming/. If the copy or the check fails, leave the source in incoming/ so the next run retries it; that file fails. An existing object at the target is overwritten. After a successful move, replace all tags on the target with exactly one tag: ADDITIONAL_TAG = the original path without incoming/. A tagging failure is only a warning (the file still counts as moved). Files moved to error/ get no tag change. Report one line per file: source, target, rule or error reason. The run fails only if a copy, check or delete failed. Moving files to error/ does not fail the run.
Plan approved by @jsandy16 at 2026-10-18T06:30:40+00:00
Code approved by @jsandy16 at 2026-10-18T13:37:42+00:00

Steps:
  1. compute_target_keys [custom] Work out target key per file from folder path (exactly one rule, else error/)
  2. move_and_tag [custom_delivery] Move files server-side, verify, delete source, tag target
Custom functions: (layout, params, ctx) -> layout; custom_delivery: (transfers, params, ctx, aws) -> results
"""
from __future__ import annotations

KIND = 'destination'

STEPS = [{'id': 'compute_target_keys',
  'op': 'custom',
  'title': 'Work out target key per file from folder path (exactly one rule, else error/)',
  'params': {'function': 'compute_target_keys'}},
 {'id': 'move_and_tag',
  'op': 'custom_delivery',
  'title': 'Move files server-side, verify, delete source, tag target',
  'params': {'function': 'move_and_tag'}}]


def compute_target_keys(layout, params, ctx):
    keys = layout["keys"]
    vars_ = layout.setdefault("vars", {})
    for path in layout["files"]:
        if keys.get(path) is not None:
            continue
        parts = path.split("/")
        study = parts[0]
        file = parts[-1]
        folders = parts[1:-1]
        last = folders[-1] if folders else None
        D = "/" + "/".join(folders) + "/"
        error_key = "error/" + path

        if "/adam/" in D:
            fmt = "adam"
        elif "/sdtm/" in D:
            fmt = "sdtm"
        elif "raw/" in D:
            fmt = "raw"
        else:
            fmt = None
        if "_adam_" in D:
            afmt = "adam"
        elif "_sdtm_" in D:
            afmt = "sdtm"
        elif "_raw_" in D or "_restricted_raw_" in D:
            afmt = "raw"
        else:
            afmt = None

        ERR = None
        matched = []  # (rule, key, errreason)

        if "/data_reuse/" in D and "/cdap_" in D and fmt:
            if "/cdap_csr" in D:
                matched.append((1, "/".join([study, "extended_primary_use", "primary", fmt, file]), ""))
            elif "_ia" in last:
                p = last.split("_")
                if len(p) < 3:
                    matched.append((1, ERR, "cdap interim folder has fewer than 3 parts"))
                else:
                    x = p[2]
                    if x.startswith("ia"):
                        ia = "ia_" + x[2:]
                        matched.append((1, "/".join([study, "extended_primary_use", "interim", fmt, ia, file]), ""))
                    else:
                        matched.append((1, ERR, "cdap third part does not start with ia"))
            else:
                p = last.split("_")
                if len(p) < 2:
                    matched.append((1, ERR, "cdap folder has fewer than 2 parts"))
                else:
                    matched.append((1, "/".join([study, "extended_primary_use", "other", fmt, p[1], file]), ""))
        if "/data_reuse/" in D and "/idap" in D and fmt:
            matched.append((2, "/".join([study, "internal_reuse", fmt, last, file]), ""))
        if "/data_reuse/" in D and "/med" in D and fmt:
            matched.append((3, "/".join([study, "external_reuse", fmt, last, file]), ""))
        if "_anon_" in D and afmt:
            if "_anon_csr" in D:
                matched.append((4, "/".join([study, "anonymised", "primary", afmt, file]), ""))
            else:
                t = last.split("_")[-1]
                if t.startswith("ia"):
                    ia = "ia_" + t[2:]
                    matched.append((4, "/".join([study, "anonymised", "interim", afmt, ia, file]), ""))
                else:
                    matched.append((4, "/".join([study, "anonymised", "other", afmt, t, file]), ""))
        if "/cdar/" in D and fmt:
            idx = None
            for i, f in enumerate(folders):
                if f.lower() == "ar":
                    idx = i
                    break
            if idx is None:
                matched.append((5, ERR, "no ar folder"))
            elif idx + 1 >= len(folders):
                matched.append((5, ERR, "no reporting level folder after ar"))
            else:
                level = folders[idx + 1].lower()
                if level in ("adam", "sdtm", "raw"):
                    matched.append((5, ERR, "reporting level is a data format"))
                elif level == "csr":
                    matched.append((5, "/".join([study, "primary", "complete", fmt, file]), ""))
                elif level.startswith("ia"):
                    x = level[2:].lstrip("_")
                    matched.append((5, "/".join([study, "primary", "interim", fmt, "ia_" + x, file]), ""))
                else:
                    matched.append((5, "/".join([study, "primary", "other", fmt, level, file]), ""))
        if ("/data_reuse/" in D and fmt
                and not any(s in D for s in ("/med", "/cdap", "/idap", "/anon", "_anon_"))):
            matched.append((6, "/".join([study, "other", fmt, last, file]), ""))
        if not any(s in D for s in ("/data_reuse/", "_anon_", "/cdar/")):
            matched.append((7, path, ""))

        if len(matched) == 1 and matched[0][1] is not None:
            keys[path] = matched[0][1]
            vars_["reason:" + path] = "rule " + str(matched[0][0])
        elif len(matched) == 0:
            keys[path] = error_key
            vars_["reason:" + path] = "no rule"
        elif len(matched) > 1:
            keys[path] = error_key
            vars_["reason:" + path] = "multiple rules: " + ", ".join(str(m[0]) for m in matched)
        else:
            keys[path] = error_key
            vars_["reason:" + path] = "cannot derive: " + matched[0][2]
    return layout


def move_and_tag(transfers, params, ctx, aws):
    results = []
    delivery = (ctx or {}).get("delivery") or {}
    sse = delivery.get("server_side_encryption")
    kms = delivery.get("kms_key_id")
    for t in transfers:
        path = t["path"]
        sb, sk = t["source_bucket"], t["source_key"]
        tb, tk = t["target_bucket"], t["target_key"]
        is_error = (tk == "error/" + path)
        reason = ""
        try:
            reason = str((params or {}).get("reason:" + path, "") or "")
        except Exception:
            reason = ""

        def fail(detail):
            aws.log.info("%s -> %s: failed: %s", sk, tk, detail)
            results.append({"path": path, "key": tk, "status": "failed", "detail": str(detail)})

        extra = {}
        if t.get("etag"):
            extra["CopySourceIfMatch"] = t["etag"]
        if sse:
            extra["ServerSideEncryption"] = sse
            if kms:
                extra["SSEKMSKeyId"] = kms
        try:
            aws.s3_destination.copy({"Bucket": sb, "Key": sk}, tb, tk,
                                    ExtraArgs=extra, SourceClient=aws.s3_source)
        except Exception as e:
            fail("copy failed: %s" % e)
            continue
        try:
            head = aws.s3_destination.head_object(Bucket=tb, Key=tk)
            if head.get("ContentLength") != t["size"]:
                fail("target size mismatch after copy")
                continue
        except Exception as e:
            fail("target check failed: %s" % e)
            continue
        try:
            aws.s3_source.delete_object(Bucket=sb, Key=sk)
        except Exception as e:
            fail("delete of source failed: %s" % e)
            continue
        if not is_error:
            try:
                aws.s3_destination.put_object_tagging(
                    Bucket=tb, Key=tk,
                    Tagging={"TagSet": [{"Key": "ADDITIONAL_TAG", "Value": path}]})
            except Exception as e:
                aws.log.warning("tagging failed for %s: %s", tk, e)
        status = "moved_to_error" if is_error else "moved"
        aws.log.info("%s -> %s: %s", sk, tk, reason or status)
        results.append({"path": path, "key": tk, "status": status, "detail": reason})
    return results


CUSTOM = {"compute_target_keys": compute_target_keys, "move_and_tag": move_and_tag}
